using Npgsql;
namespace LoyaltyService.Infrastructure; public static class DatabaseInitializer { public static async Task InitializeAsync(string cs) { for (var i = 1; ; i++) try { await using var db = new NpgsqlConnection(cs); await db.OpenAsync(); const string sql = """CREATE TABLE IF NOT EXISTS loyalty(id SERIAL PRIMARY KEY,username varchar(80) UNIQUE NOT NULL,reservation_count int NOT NULL DEFAULT 0,status varchar(80) NOT NULL CHECK(status IN ('BRONZE','SILVER','GOLD')),discount int NOT NULL); INSERT INTO loyalty(username,reservation_count,status,discount) VALUES('Test Max',25,'GOLD',10) ON CONFLICT(username) DO NOTHING;"""; await using var c = new NpgsqlCommand(sql, db); await c.ExecuteNonQueryAsync(); return; } catch when (i < 30) { await Task.Delay(2000); } } }
